<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>false</code></td>
</tr>
<tr>
<td>model-value <strong>(v-model)</strong></td>
<td>绑定值</td>
<td><code v-pre>string| number| Record&lt;string, any&gt;| (    | string    | number    | Record&lt;string, any&gt;    | (string | number | Record&lt;string, any&gt;)[]  )[]| undefined</code></td>
<td style="text-align:center"><code v-pre>-</code></td>
</tr>
<tr>
<td>default-value</td>
<td>默认值（非受控状态）</td>
<td><code v-pre>string| number| Record&lt;string, any&gt;| (    | string    | number    | Record&lt;string, any&gt;    | (string | number | Record&lt;string, any&gt;)[]  )[]| undefined</code></td>
<td style="text-align:center"><code v-pre>'' | undefined | []</code></td>
</tr>
<tr>
<td>options</td>
<td>级联选择器的选项</td>
<td><code v-pre>CascaderOption[]</code></td>
<td style="text-align:center"><code v-pre>[]</code></td>
</tr>
<tr>
<td>disabled</td>
<td>是否禁用</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>false</code></td>
</tr>
<tr>
<td>error</td>
<td>是否为错误状态</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>false</code></td>
</tr>
<tr>
<td>size</td>
<td>选择框的大小</td>
<td><code v-pre>'xs' | 'sm' | 'md' | 'lg' | 'xl'</code></td>
<td style="text-align:center"><code v-pre>'md'</code></td>
</tr>
<tr>
<td>filterable</td>
<td>是否允许搜索</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>false (single) | true (multiple)</code></td>
</tr>
<tr>
<td>clearable</td>
<td>是否允许清除</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>false</code></td>
</tr>
<tr>
<td>input-value <strong>(v-model)</strong></td>
<td>输入框的值</td>
<td><code v-pre>string</code></td>
<td style="text-align:center"><code v-pre>-</code></td>
</tr>
<tr>
<td>default-input-value</td>
<td>输入框的默认值（非受控状态）</td>
<td><code v-pre>string</code></td>
<td style="text-align:center"><code v-pre>''</code></td>
</tr>
<tr>
<td>popup-visible <strong>(v-model)</strong></td>
<td>是否显示下拉框</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>-</code></td>
</tr>
<tr>
<td>expand-trigger</td>
<td>展开下一级的触发方式</td>
<td><code v-pre>'click' | 'hover'</code></td>
<td style="text-align:center"><code v-pre>'click'</code></td>
</tr>
<tr>
<td>default-popup-visible</td>
<td>是否默认显示下拉框（非受控状态）</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>false</code></td>
</tr>
<tr>
<td>placeholder</td>
<td>占位符</td>
<td><code v-pre>string</code></td>
<td style="text-align:center"><code v-pre>-</code></td>
</tr>
<tr>
<td>filter-option</td>
<td>自定义选项过滤方法</td>
